"""
Generate a proper print-ready PDF of The Future is Unwritten.
Uses the revised markdown and builds a complete HTML document with:
- Cover page with book cover image
- Proper A4 formatting
- Full book content
"""
import markdown
import os, re

INPUT_MD = "/home/bob/books/The_Unwritten_Future/THE_UNWRITTEN_FUTURE_REVISED.md"
OUTPUT_PDF = "/home/bob/books/The_Unwritten_Future/The_Future_Is_Unwritten.pdf"
COVER_IMAGE = "/home/bob/books/The_Unwritten_Future/THE_FUTURE_IS_UNWRITTEN_COVER.png"

# Read markdown
with open(INPUT_MD, 'r', encoding='utf-8') as f:
    md_text = f.read()

# Convert to HTML - use all extensions
html_body = markdown.markdown(md_text, extensions=[
    'extra', 'smarty', 'codehilite', 'toc', 'sane_lists'
])

# CSS for a proper book-style A4 PDF
css = """
@page {
    size: A4;
    margin: 2.2cm 2.5cm 2.2cm 2.5cm;
    @bottom-center {
        content: counter(page);
        font-family: Georgia, "Times New Roman", serif;
        font-size: 10pt;
        color: #555;
    }
    @top-center {
        content: "The Future is Unwritten — Robert Mills";
        font-family: Georgia, serif;
        font-size: 8pt;
        color: #999;
        font-style: italic;
    }
}

@page:first {
    @top-center { content: none; }
    @bottom-center { content: none; }
}

body {
    font-family: Georgia, "Times New Roman", serif;
    font-size: 12pt;
    line-height: 1.7;
    color: #111;
    orphans: 3;
    widows: 3;
    text-align: justify;
}

/* ===== COVER PAGE ===== */
.cover-page {
    page-break-after: always;
    text-align: center;
    padding-top: 0;
    margin: 0;
    position: relative;
    width: 100%;
    height: 100%;
}

.cover-page img {
    width: 100%;
    height: auto;
    max-height: 95vh;
    object-fit: contain;
}

/* ===== COPYRIGHT PAGE ===== */
.copyright-page {
    page-break-after: always;
    text-align: center;
    padding-top: 6cm;
    font-size: 10pt;
    color: #666;
    line-height: 2;
}
.copyright-page h1 {
    font-size: 18pt;
    color: #111;
    margin-bottom: 0.5cm;
}
.copyright-page p {
    text-indent: 0;
    text-align: center;
}

/* ===== TITLE PAGE ===== */
.title-page {
    page-break-after: always;
    text-align: center;
    padding-top: 5cm;
}
.title-page h1 {
    font-size: 26pt;
    letter-spacing: 2pt;
    margin-bottom: 1cm;
    text-align: center;
    page-break-before: avoid;
}
.title-page .author {
    font-size: 16pt;
    font-style: italic;
    color: #444;
    text-align: center;
}

/* ===== HEADINGS ===== */
h1 {
    text-align: center;
    font-size: 20pt;
    margin-top: 2.5cm;
    margin-bottom: 1cm;
    page-break-before: always;
    page-break-after: avoid;
    font-weight: bold;
    color: #111;
    letter-spacing: 1pt;
    line-height: 1.3;
}

h2 {
    text-align: center;
    font-size: 16pt;
    margin-top: 2cm;
    margin-bottom: 0.8cm;
    page-break-before: always;
    page-break-after: avoid;
    font-weight: bold;
    color: #222;
}

h3 {
    font-size: 13pt;
    margin-top: 1.2cm;
    margin-bottom: 0.5cm;
    page-break-after: avoid;
    font-weight: bold;
    color: #333;
}

h4 {
    font-size: 12pt;
    margin-top: 0.8cm;
    margin-bottom: 0.4cm;
    font-weight: bold;
    font-style: italic;
    color: #444;
    page-break-after: avoid;
}

/* ===== PARAGRAPHS ===== */
p {
    margin: 0.15em 0;
    text-indent: 1.5em;
}

/* First paragraph after a heading - no indent */
h1 + p, h2 + p, h3 + p, h4 + p {
    text-indent: 0;
}

em, i {
    font-style: italic;
}

strong, b {
    font-weight: bold;
}

/* ===== BLOCKQUOTES ===== */
blockquote {
    font-style: italic;
    margin: 0.8em 2em;
    color: #555;
    font-size: 11pt;
    border-left: 3pt solid #bbb;
    padding-left: 1.2em;
}
blockquote p {
    text-indent: 0;
}

/* ===== HORIZONTAL RULES ===== */
hr {
    border: none;
    border-top: 1pt solid #ddd;
    margin: 1cm 4cm;
}

/* ===== LISTS ===== */
ul, ol {
    margin: 0.3em 0;
    padding-left: 2.5em;
}
li {
    margin: 0.15em 0;
}

/* ===== CODE ===== */
code {
    font-family: "Courier New", monospace;
    font-size: 10pt;
    background: #f4f4f4;
    padding: 2pt 4pt;
}
pre {
    font-family: "Courier New", monospace;
    font-size: 9pt;
    background: #f4f4f4;
    padding: 0.5em;
    border: 1pt solid #ddd;
    overflow-x: auto;
    white-space: pre-wrap;
}

/* ===== TABLES ===== */
table {
    border-collapse: collapse;
    margin: 1em auto;
    font-size: 11pt;
}
td, th {
    border: 1pt solid #ccc;
    padding: 6pt 10pt;
    text-align: left;
}
th {
    background: #eee;
    font-weight: bold;
}
"""

# Remove the first h1 from html_body since we have a cover/title page
# Find first h1
first_h1_match = re.search(r'<h1>.*?</h1>', html_body)
first_h1 = first_h1_match.group(0) if first_h1_match else ''

# Check if the body starts with the title
html_body = html_body.lstrip()

