{"content": "#!/usr/bin/env python3
"""Generate expanded transitions via OpenRouter API, then insert them into the manuscript."""

import requests, json, os, re, time
import subprocess

# Get OpenRouter API key
r = subprocess.run("grep -o 'sk-or[^ \"]*' ~/.hermes/config.yaml 2>/dev/null | head -1", shell=True, capture_output=True, text=True)
OR_KEY = r.stdout.strip()

if not OR_KEY:
    r2 = subprocess.run("echo $OPENROUTER_API_KEY", shell=True, capture_output=True, text=True)
    OR_KEY = r2.stdout.strip()

print(f"OpenRouter API key: {OR_KEY[:15]}..." if OR_KEY else "No OR key found")
if not OR_KEY:
    print("ERROR: Need OpenRouter API key")
    exit(1)

URL = "https://openrouter.ai/api/v1/chat/completions"
HEADERS = {
    "Authorization": f"Bearer {OR_KEY}",
    "Content-Type": "application/json",
    "HTTP-Referer": "http://localhost",
    "X-Title": "Hermes Agent"
}

# Define each transition
transitions = [
    {
        "title": "Transition: From Bobs Childhood to the Spark of Sputnik",
        "context": "Bridges Bobs childhood (dog Mr. Chips, strict Navy veteran father) and the arrival of Sputnik in 1957. The transition should weave: physiology of a seven-year-old brain processing death and loss then expanding to cosmic wonder; Space Race dawning; suburban 1950s Midwest; cortisol and dopamine encoding both grief and wonder; Bob moving from small world of suburban dog to looking up at the sky.",
    },
    {
        "title": "Transition: From Sputnik to the Family Legacy in the Garage",
        "context": "Bridges Sputnik/family history and the garage building years. Weave: physiology of child discovering hands-on creation vs passive consumption; mirror neurons firing as Bob watches father build; garage as neural sanctuary where competence mattered over compliance; American middle-class families having time for hobbies in the late 1950s.",
    },
    {
        "title": "Transition: From the Garage Years to the Spark of Technology",
        "context": "Bridges Bobs garage building years and his discovery of computers and electronics at the TV repair shop. Weave: physiology of learning electronics in a teenagers brain; transition from analog to digital culture; smell of solder and glow of vacuum tubes becoming hum of early silicon; nervous system adapting to increasingly abstract challenges.",
    },
    {
        "title": "Transition: From High School Discovery to University Life",
        "context": "Bridges Bobs high school years (analog weather computer, science fair) and entering Michigan State. Weave: first-generation college student facing new intellectual terrain; Vietnam War era and draft lottery anxiety; impostor syndrome versus academic discovery; working at TV repair shop training executive function; contrast between working-class preparation and wealthy classmates.",
    },
    {
        "title": "Transition: From College Years to Aerospace Career",
        "context": "Bridges Bobs university years and aerospace engineering career. Weave: physiology of young professional transitioning from theory to life-and-death practice; Cold War aerospace industry; stress physiology when stakes include pilot safety; transition from student adrenaline to professional cortisol; nervous system adapting to classified work with real consequences.",
    },
    {
        "title": "Transition: From Career Stability to Fatherhood",
        "context": "Bridges Bobs stable engineering career and the arrival of his two children. Weave: oxytocin from newborn competing with cortisol from career pressures; brain rewiring for empathy alongside executive function; 1970s-80s changing fatherhood expectations; breaking cycle of distant fatherhood he received from his own father.",
    },
    {
        "title": "Transition: From Stability to the Storm",
        "context": "Bridges Bobs stable career and family life with Nancys cancer diagnosis. Weave: physiology of normalcy about to be shattered; doctor delivering devastating news; vagus nerve responding to shock; the future Bob planned replaced by timeline he never chose; both nervous systems adapting to same devastating information differently.",
    },
    {
        "title": "Transition: From the Depths of Grief Toward New Possibility",
        "context": "Bridges grief after Nancys death and Bobs meeting of Cindy. Weave: cortisol declining but never normalizing; first laugh after tragedy and the guilt it triggers; gradual return of dopamine; neural plasticity allowing the heart to consider attachment again after profound loss; courage of considering connection despite fear of more loss.",
    },
    {
        "title": "Transition: The Promise of What Remains",
        "context": "Final transition bridging the memoirs main body and the epilogue. Weave: the biology of looking back with clarity; how memory itself is a physiological process being shaped by age; historical context of how memoir writing was done across eras; what it feels like in the body to write about the life one has lived; the nervous system at rest after decades of adaptation.",
    },
]

generated = []

for i, t in enumerate(transitions):
    print(f"\nGenerating transition {i+1}/{len(transitions)}: {t['title'][:50]}...")

    prompt = f"""Write a memoir transition section of approximately 5000 characters (about 700-800 words). 

Title: {t['title']}

This transition is for a memoir called "The Future is Unwritten" about Bob Mills, an engineer who navigated the Space Age, built a career in aerospace engineering, raised a family, lost his first wife Nancy to cancer, married again, and reflected on his life journey.

Context from the book:
{t['context']}

Requirements:
- Write in THIRD PERSON only (Bob/he/his/him - never I/me/my/we/us in narration)
- Seamlessly blend historical events with physiological/biological effects on Bob's brain and body
- Include specific neurotransmitter and brain structure references (cortisol, dopamine, amygdala, hippocampus, oxytocin, prefrontal cortex, etc.)
- Connect Bob's individual experience to broader historical moments
- Write in the style of a bestselling memoir - literary but accessible
- Be specific and grounded in sensory details
- Do NOT include the title in the output - just write the transition prose itself
- End with a phrase that naturally leads into the next chapter
- Target approximately 5000 characters
"""

    payload = {
        "model": "deepseek/deepseek-v3-base",
        "messages": [
            {"role": "system", "content": "You are a skilled memoir writer working on a project. Write in third person, blending historical context with biological and neurological details. The subject is Bob Mills, an American engineer born in the 1930s. Never use first person pronouns (I, me, my, we, us) in narration."},
            {"role": "user", "content": prompt}
        ],
        "max_tokens": 4000,
        "temperature": 0.7,
    }

    resp = requests.post(URL, headers=HEADERS, json=payload, timeout=120)
    data = resp.json()

    if 'choices' in data and data['choices']:
        text = data['choices'][0]['message']['content'].strip()
        # Remove any title prefix the model might have added
        text = re.sub(r'^#+\s+.*?transition.*?[\n\r]', '', text, flags=re.IGNORECASE)
        text = text.strip()

        t['generated'] = text
        words = len(text.split())
        chars = len(text)
        print(f"  Generated: {words} words, {chars} characters {'[OK]' if chars >= 4000 else '[SHORT]'}")

        # Save to individual file
        with open(f'/tmp/transition_{i+1}.txt', 'w') as f:
            f.write(text)
    else:
        print(f"  ERROR: {data.get('error', resp.text[:200])}")
        t['generated'] = None

    time.sleep(1)

# Save all generated text
with open('/tmp/generated_transitions.json', 'w') as f:
    json.dump([{k: v for k, v in t.items() if k != 'generated'} | 
               {'text_preview': (t.get('generated') or '')[:100], 'text_len': len(t.get('generated') or '')} 
               for t in transitions], f, indent=2, ensure_ascii=False)

print("\n=== Summary ===")
for t in transitions:
    chars = len(t.get('generated', '') or '')
    print(f"  {t['title'][:55]}: {chars} chars")
ok = sum(1 for t in transitions if len(t.get('generated', '') or '') >= 4000)
print(f"\n{ok}/{len(transitions)} transitions generated successfully")
