import re

# Find each transition's end position
transitions = []
for m in re.finditer(r'### Transition: ([^\n]+)', md):
    title = m.group(1)
    start = m.start()
    after = md[start+10:]
    next_sec = re.search(r'\n\n(###|##)', after)
    if next_sec:
        end = start + 10 + next_sec.start()
    else:
        end = len(md)
    transitions.append({'title': title, 'start': start, 'end': end, 'chars': end - start})

for t in transitions:
    print(f"{t['title'][:60]:60s} {t['chars']:5d} c")
