{"code": "with open('/home/bob/books/The_Unwritten_Future/THE_UNWRITTEN_FUTURE_FINAL.md') as f:
    md = f.read()
import re

# Find major section boundaries (only # or ## lines that start with Part/Chapter/Epilogue/Transition)
sections = []
for m in re.finditer(r'\n(#{1,2}) ((?:Part|Chapter|Epilogue|Transition):[^\n]*)', md):
    level = m.group(1)
    title = m.group(2).strip()
    sections.append((m.start(), title, level))

print(f"Found {len(sections)} major sections:")
for pos, title, level in sections:
    # Find end of this section
    end = md.find('\n##', pos + 10)
    if end < 0 or not md[end+2:].strip().startswith(('# Part', '# Chapter', '# Epilogue', '# Transition')):
        # Check for single #
        end2 = md.find('\n# ', pos + 10)
        if end2 > 0 and (end < 0 or end2 < end):
            end = end2
    if end <= pos + 10:
        end = len(md)
    content_preview = md[pos+3:pos+100].strip()
    char_count = (end if end > pos+10 else len(md)) - pos
    print(f"  {title[:60]:60s} ~{char_count:6d}c -> {content_preview[:50]}...")
"}

